<?php include 'conexao.php';$result=$conn->query('SELECT * FROM produtos ORDER BY id DESC');$total=$result->num_rows;?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Produtos • CRUD</title><link rel="stylesheet" href="style.css"></head><body><header class="navbar"><div class="container nav-inner"><a class="brand" href="index.php">CRUD<span>Produtos</span></a><div class="nav-badge">PHP + MySQL + Docker</div></div></header><main class="main"><div class="container"><section class="hero"><div><div class="eyebrow">Painel de produtos</div><h1 class="title">Seus produtos</h1><p class="subtitle">Cadastre, edite e organize seus produtos em um só lugar.</p></div><a class="btn btn-primary" href="novo.php">＋ Novo produto</a></section><section class="card"><div class="card-head"><h2>Lista de produtos</h2><span class="count"><?=$total?> <?=$total==1?'item':'itens'?></span></div><?php if($total):?><div class="table-wrap"><table class="table"><thead><tr><th>#</th><th>Produto</th><th>Descrição</th><th>Cadastrado em</th><th>Ações</th></tr></thead><tbody><?php while($p=$result->fetch_assoc()):?><tr><td class="product-id">#<?= (int)$p['id']?></td><td class="product-name"><?=htmlspecialchars($p['nome'])?></td><td class="desc"><?=htmlspecialchars($p['descricao']?:'Sem descrição')?></td><td class="date"><?=date('d/m/Y H:i',strtotime($p['data_cadastro']))?></td><td><div class="actions"><a class="btn btn-edit" href="editar.php?id=<?=(int)$p['id']?>">✎ Editar</a><a class="btn btn-danger" href="excluir.php?id=<?=(int)$p['id']?>" onclick="return confirm('Deseja realmente excluir este produto?')">Excluir</a></div></td></tr><?php endwhile;?></tbody></table></div><?php else:?><div class="empty"><div class="empty-icon">📦</div><h3>Nenhum produto cadastrado</h3><p>Comece adicionando seu primeiro produto.</p></div><?php endif;?></section></div></main></body></html>